class Solution:
    def orderByGuide(self, items: List[int], guide: List[int]) -> List[int]:
        out, used = [], [False] * len(items)
        for g in guide:
            for i, x in enumerate(items):
                if x == g:
                    out.append(x)
                    used[i] = True
        rest = sorted(x for i, x in enumerate(items) if not used[i])
        return out + rest

