class Solution {
    public int[] orderByGuide(int[] items, int[] guide) {
        int n = items.length, w = 0;
        int[] out = new int[n];
        boolean[] used = new boolean[n];
        for (int g : guide)
            for (int i = 0; i < n; i++)
                if (items[i] == g) { out[w++] = g; used[i] = true; }
        int start = w;
        for (int i = 0; i < n; i++) if (!used[i]) out[w++] = items[i];
        Arrays.sort(out, start, n);
        return out;
    }
}

