class Solution {
public:
    vector<int> orderByGuide(vector<int>& items, vector<int>& guide) {
        int n = items.size();
        vector<int> out;
        vector<char> used(n, 0);
        for (int g : guide)
            for (int i = 0; i < n; i++)
                if (items[i] == g) { out.push_back(g); used[i] = 1; }
        size_t start = out.size();
        for (int i = 0; i < n; i++) if (!used[i]) out.push_back(items[i]);
        sort(out.begin() + start, out.end());
        return out;
    }
};

