static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int* orderByGuide(int* items, int itemsSize, int* guide, int guideSize, int* returnSize) {
    int n = itemsSize, w = 0;
    int* out = malloc(n * sizeof(int));
    char* used = calloc(n, 1);
    for (int g = 0; g < guideSize; g++)
        for (int i = 0; i < n; i++)
            if (items[i] == guide[g]) { out[w++] = guide[g]; used[i] = 1; }
    int start = w;
    for (int i = 0; i < n; i++) if (!used[i]) out[w++] = items[i];
    qsort(out + start, n - start, sizeof(int), cmp_int);
    free(used);
    *returnSize = n;
    return out;
}

