class Solution {
    public int[] orderByGuide(int[] items, int[] guide) {
        Map<Integer, Integer> rank = new HashMap<>();
        for (int i = 0; i < guide.length; i++) rank.put(guide[i], i);
        int after = guide.length;
        Integer[] boxed = Arrays.stream(items).boxed().toArray(Integer[]::new);
        Arrays.sort(boxed, Comparator.<Integer>comparingInt(x -> rank.getOrDefault(x, after)).thenComparingInt(x -> x));
        return Arrays.stream(boxed).mapToInt(Integer::intValue).toArray();
    }
}

