class Solution {
public:
    vector<int> orderByGuide(vector<int>& items, vector<int>& guide) {
        unordered_map<int, int> rank;
        for (int i = 0; i < (int) guide.size(); i++) rank[guide[i]] = i;
        int after = guide.size();
        vector<pair<int, int>> keyed;
        for (int x : items) keyed.push_back({rank.count(x) ? rank[x] : after, x});
        sort(keyed.begin(), keyed.end());
        vector<int> out;
        for (auto& [r, x] : keyed) out.push_back(x);
        return out;
    }
};

