typedef struct { int value, rank; } Key;

static int by_value(const void* x, const void* y) {
    const Key *a = x, *b = y;
    return (a->value > b->value) - (a->value < b->value);
}

static int by_key(const void* x, const void* y) {
    const Key *a = x, *b = y;
    if (a->rank != b->rank) return a->rank - b->rank;
    return (a->value > b->value) - (a->value < b->value);
}

int* orderByGuide(int* items, int itemsSize, int* guide, int guideSize, int* returnSize) {
    Key* g = malloc(guideSize * sizeof(Key));
    for (int i = 0; i < guideSize; i++) g[i] = (Key){guide[i], i};
    qsort(g, guideSize, sizeof(Key), by_value);
    Key* keyed = malloc(itemsSize * sizeof(Key));
    for (int i = 0; i < itemsSize; i++) {
        Key probe = {items[i], 0};
        Key* hit = bsearch(&probe, g, guideSize, sizeof(Key), by_value);
        keyed[i] = (Key){items[i], hit ? hit->rank : guideSize};
    }
    qsort(keyed, itemsSize, sizeof(Key), by_key);
    int* out = malloc(itemsSize * sizeof(int));
    for (int i = 0; i < itemsSize; i++) out[i] = keyed[i].value;
    free(g); free(keyed);
    *returnSize = itemsSize;
    return out;
}
